class Solution {
  public int preimageSizeFZF(int k) {
    // the count is 5 if some x! has exactly k trailing zeros, otherwise 0
    return (int) (firstWithAtLeast(k + 1L) - firstWithAtLeast(k));
  }

  private long firstWithAtLeast(long zeros) {
    long lo = 0, hi = 5 * (zeros + 1);
    while (lo < hi) {
      long mid = (lo + hi) >>> 1;
      if (trailingZeros(mid) >= zeros) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }

  private long trailingZeros(long x) {
    long count = 0;
    for (; x > 0; x /= 5) count += x / 5;
    return count;
  }
}
